100→
101→      {/* Main chat area */}
102→      <div className="flex min-w-0 flex-1 flex-col">
103→        <Chat
104→          connected={connected}
105→          loading={!initialLoadDone || historyLoading}
106→          status={activeStatus}
107→          messages={activeMessages}
108→          rawMessages={activeRawMessages}
109→          onSendMessage={sendMessage}
110→          onSpawnAgent={spawnAgent}
111→          onRespondToControl={respondToControl}
112→          onRespondToUserQuestion={respondToUserQuestion}
113→          showTasks={showTasks}
114→          onToggleTasks={() => setShowTasks((v) => !v)}
115→          onToggleSidebar={() => setSidebarOpen((v) => !v)}
116→        />
117→      </div>
118→
