  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. No agent is auto-selected — the user stays on the new-agent
 18→ *    creation screen until they explicitly pick or spawn an agent.
 19→ *
 20→ * ## Lazy history loading
 21→ *
 22→ * Message histories are loaded on demand. When `activeAgentId` changes
 23→ * and the agent hasn't been loaded yet, the hook sends
 24→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 25→ * When the server responds with `message_history`, the agent's messages
 26→ * are populated and `historyLoading` becomes false.
 27→ *
 28→ * The `loadedAgents` Set tracks which agents have been fetched so that
 29→ * switching back to a previously viewed agent is instant.
 30→ *
 31→ * ## Resilience features
 32→ *
 33→ * - Handles `message_history` replay from server on demand.
 34→ * - Handles `cli_disconnected` / `cli_connected` events.
 35→ * - Deduplicates messages using a per-agent processed count.
 36→ * - Robust reconnection guard (clears previous timer before scheduling).
 37→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 38→ *
 39→ * ## Logging
 40→ *
 41→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 42→ * in the browser console to debug connection and message delivery issues.
 43→ */
 44→
 45→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 46→import type {
 47→  AgentInfo,
 48→  AgentStatus,
 49→  ChatMessage,
 50→  ClaudeAssistant,
 51→  ClaudeControlRequest,
 52→  ClaudeMessage,
 53→  ClaudeResult,
 54→  ClaudeSystemInit,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→} from "@/lib/types";
 65→
 66→/** Connect to the WS server on the same host the page was loaded from. */
 67→const WS_URL =
 68→  typeof window !== "undefined"
 69→    ? `ws://${window.location.hostname}:9900/browser`
 70→    : "ws://localhost:9900/browser";
 71→
 72→/** Per-agent client state. */
 73→export interface AgentClientState {
 74→  status: AgentStatus;
 75→  messages: ChatMessage[];
 76→  /** Raw Claude NDJSON messages for debug view. */
 77→  rawMessages: ClaudeMessage[];
 78→  label: string;
 79→  tmuxSession: string | null;
 80→  createdAt: number;
 81→}
 82→
 83→/**
 84→ * Extract displayable text from a Claude assistant message.
 85→ * Content blocks may be text, tool_use, or tool_result — each is
 86→ * handled defensively since the array structure can vary.
 87→ */
 88→function extractText(msg: ClaudeAssistant): string {
 89→  const blocks = msg.message?.content;
 90→  if (!blocks || !Array.isArray(blocks)) return "";
 91→  return blocks
 92→    .map((b) => {
 93→      if (b.type === "text") return b.text;
 94→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 95→      if (b.type === "tool_result") {
 96→        const c = (b as { content?: unknown }).content;
 97→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 98→      }
 99→      return "";
100→    })
101→    .filter(Boolean)
102→    .join("\n");
103→}
104→
105→/** Module-level counter for generating unique message IDs. */
106→let msgCounter = 0;
107→function nextId() {
108→  return `msg-${Date.now()}-${++msgCounter}`;
109→}
110→
111→/**
112→ * Extract a stable dedup key from a relay message, if present.
113→ *
114→ * Claude NDJSON sends cumulative snapshots for two message types:
115→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
116→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
117→ *
118→ * Returns the key or null for non-deduplicable messages.
119→ */
120→function getRelayDedupKey(relayMsg: ServerMessage): string | null {
121→  if (relayMsg.type !== "relay") return null;
122→  const inner = relayMsg.message;
123→  if (inner.type === "assistant") {
124→    return (inner as { message?: { id?: string } }).message?.id ?? null;
125→  }
126→  if (inner.type === "user") {
127→    return (inner as { uuid?: string }).uuid ?? null;
128→  }
129→  return null;
130→}
131→
132→/**
133→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
134→ * Used both for live messages and for replaying message_history.
135→ *
136→ * When a relay message has a stable dedup key (assistant message.id or user uuid),
137→ * that key is used as the ChatMessage `id` so that cumulative snapshots produce
138→ * ChatMessages with the same identity — enabling in-place replacement.
139→ */
140→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
141→  if (relayMsg.type === "relay") {
142→    const msg = relayMsg.message;
143→    const dedupKey = getRelayDedupKey(relayMsg);
144→
145→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
146→      const init = msg as ClaudeSystemInit;
147→      return {
148→        id: nextId(),
149→        role: "system",
150→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
151→        timestamp: Date.now(),
152→      };
153→    }
154→
155→    if (msg.type === "user") {
156→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
157→      // Only render human-typed user messages (string content).
158→      // CLI tool_result messages have array content — these are internal
159→      // protocol messages and are only visible in the raw message viewer.
160→      if (typeof rawContent !== "string") return null;
161→      if (!rawContent.trim()) return null;
162→      return {
163→        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
164→        role: "user",
165→        content: rawContent,
166→        timestamp: Date.now(),
167→      };
168→    }
169→
170→    if (msg.type === "assistant") {
171→      const assistant = msg as ClaudeAssistant;
172→      const text = extractText(assistant);
173→      if (!text) return null;
174→
175→      const blocks = assistant.message?.content ?? [];
176→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
177→      const toolCalls: ToolCallInfo[] = blocks
178→        .filter((b) => b.type === "tool_use")
179→        .map((b) => ({
180→          name: (b as { name: string }).name,
181→          toolUseId: (b as { id: string }).id,
182→        }));
183→      const isToolOnly = !hasText && toolCalls.length > 0;
184→
185→      return {
186→        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
187→        role: "assistant",
188→        content: text,
189→        timestamp: Date.now(),
190→        toolCalls,
191→        isToolOnly,
192→      };
193→    }
194→
195→    if (msg.type === "result") {
196→      const result = msg as ClaudeResult;
197→      const cost = result.total_cost_usd ?? result.cost_usd ?? 0;
198→      const summary = result.is_error
199→        ? `Error: ${result.error}`
200→        : `Done — ${result.num_turns ?? "?"} turns, $${cost.toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
201→      return {
202→        id: nextId(),
203→        role: "system",
204→        content: summary,
205→        timestamp: Date.now(),
206→      };
207→    }
208→
209→    if (msg.type === "control_request") {
210→      const cr = msg as ClaudeControlRequest;
211→
212→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
213→      if (cr.request.tool_name === "AskUserQuestion") {
214→        const input = cr.request.input as { questions?: UserQuestion[] };
215→        const questions = Array.isArray(input.questions) ? input.questions : [];
216→        return {
217→          id: nextId(),
218→          role: "system",
219→          content: "Question from Claude",
220→          timestamp: Date.now(),
221→          userQuestion: {
222→            requestId: cr.request_id,
223→            questions,
224→          },
225→        };
226→      }
227→
228→      return {
229→        id: nextId(),
230→        role: "system",
231→        content: `Tool approval requested: ${cr.request.tool_name}`,
232→        timestamp: Date.now(),
233→        controlRequest: {
234→          id: cr.request_id,
235→          tool_name: cr.request.tool_name,
236→          input: cr.request.input,
237→          description: cr.request.description,
238→        },
239→      };
240→    }
241→  }
242→
243→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
244→    return {
245→      id: nextId(),
246→      role: "system",
247→      content: `Error: ${relayMsg.error}`,
248→      timestamp: Date.now(),
249→    };
250→  }
251→
252→  return null;
253→}
254→
255→/**
256→ * Find the index of an existing raw message that should be replaced by this relay.
257→ * Searches from the end for speed (cumulative snapshots arrive sequentially).
258→ */
259→function findLastRawIndex(rawMessages: ClaudeMessage[], relay: ServerMessage): number {
260→  if (relay.type !== "relay") return -1;
261→  const inner = relay.message;
262→  if (inner.type === "assistant") {
263→    const id = (inner as { message?: { id?: string } }).message?.id;
264→    if (!id) return -1;
265→    for (let i = rawMessages.length - 1; i >= 0; i--) {
266→      const r = rawMessages[i];
267→      if (r.type === "assistant" && (r as { message?: { id?: string } }).message?.id === id) return i;
268→    }
269→  }
270→  if (inner.type === "user") {
271→    const uuid = (inner as { uuid?: string }).uuid;
272→    if (!uuid) return -1;
273→    for (let i = rawMessages.length - 1; i >= 0; i--) {
274→      const r = rawMessages[i];
275→      if (r.type === "user" && (r as { uuid?: string }).uuid === uuid) return i;
276→    }
277→  }
278→  return -1;
279→}
280→
281→/** Console logger with [thos] prefix for easy filtering. */
282→function log(...args: unknown[]) {
283→  console.log("[thos-ws]", ...args);
284→}
285→
286→export function useWebSocket() {
287→  const wsRef = useRef<WebSocket | null>(null);
288→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
289→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
290→  const closingRef = useRef(false);
291→  const [connected, setConnected] = useState(false);
292→  /** True once we've received the initial agent_list from the server. */
293→  const [initialLoadDone, setInitialLoadDone] = useState(false);
294→
295→  // Multi-agent state
296→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
297→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
298→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
299→
300→  // Task state
301→  const [tasks, setTasks] = useState<Task[]>([]);
302→
303→  // Per-agent deduplication: track count of processed messages per agent
304→  // to avoid duplicating messages already in local state during history replay.
305→  const processedCountRef = useRef<Map<string, number>>(new Map());
306→
307→  // Track which agents have had their history loaded (lazy loading).
308→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
309→
310→  /** Immutably update a single agent's state in the Map. */
311→  const updateAgent = useCallback(
312→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
313→      setAgents((prev) => {
314→        const existing = prev.get(agentId);
315→        if (!existing) return prev;
316→        const next = new Map(prev);
317→        next.set(agentId, updater(existing));
318→        return next;
319→      });
320→    },
321→    []
322→  );
323→
324→  const connect = useCallback(() => {
325→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
326→    if (wsRef.current) {
327→      wsRef.current.close();
328→      wsRef.current = null;
329→    }
330→
331→    // Reset dedup counts on new connection — server will send fresh history
332→    processedCountRef.current.clear();
333→    setInitialLoadDone(false);
334→    setLoadedAgents(new Set());
335→
336→    log("connecting to", WS_URL);
337→    const ws = new WebSocket(WS_URL);
338→    wsRef.current = ws;
339→
340→    ws.onopen = () => {
341→      log("connected");
342→      setConnected(true);
343→    };
344→
345→    ws.onclose = () => {
346→      log("disconnected, closingRef =", closingRef.current);
347→      setConnected(false);
348→      wsRef.current = null;
349→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
350→      if (closingRef.current) return;
351→      // Reconnection guard: clear any existing timer before scheduling
352→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
353→      log("scheduling reconnect in 2s");
354→      reconnectTimer.current = setTimeout(() => connect(), 2000);
355→    };
356→
357→    ws.onerror = (e) => {
358→      log("error", e);
359→      // onclose will fire after onerror, which triggers reconnect
360→    };
361→
362→    ws.onmessage = (event) => {
363→      let data: ServerMessage;
364→      try {
365→        data = JSON.parse(event.data as string);
366→      } catch {
367→        return;
368→      }
369→
370→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
371→
372→      // ── task_list: full task list from server ──
373→      if (data.type === "task_list") {
374→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
375→        setTasks((data as ServerTaskList).tasks);
376→        return;
377→      }
378→
379→      // ── task_updated: single task changed ──
380→      if (data.type === "task_updated") {
381→        const updated = (data as ServerTaskUpdated).task;
382→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
383→        return;
384→      }
385→
386→      // ── task_deleted: remove task ──
387→      if (data.type === "task_deleted") {
388→        const deletedId = (data as ServerTaskDeleted).taskId;
389→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
390→        return;
391→      }
392→
393→      // ── message_history: replay full history from server ──
394→      if (data.type === "message_history") {
395→        const historyMsg = data as ServerMessageHistory;
396→        const agentId = historyMsg.agentId;
397→        const serverMessages = historyMsg.messages;
398→        log("message_history:", agentId, serverMessages.length, "raw msgs");
399→
400→        // Convert all server messages to ChatMessages + extract raw Claude messages
401→        const chatMessages: ChatMessage[] = [];
402→        const rawMessages: ClaudeMessage[] = [];
403→        for (const sm of serverMessages) {
404→          if (sm.type === "relay") {
405→            rawMessages.push(sm.message);
406→          }
407→          const cm = relayChatMessage(agentId, sm);
408→          if (cm) chatMessages.push(cm);
409→        }
410→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
411→
412→        // Always replace local messages with server history (source of truth).
413→        setAgents((prev) => {
414→          const existing = prev.get(agentId);
415→          if (!existing) {
416→            log("message_history:", agentId, "agent not in map yet, creating");
417→            const next = new Map(prev);
418→            next.set(agentId, {
419→              status: "idle",
420→              messages: chatMessages,
421→              rawMessages,
422→              label: "",
423→              tmuxSession: null,
424→              createdAt: 0,
425→            });
426→            return next;
427→          }
428→          const next = new Map(prev);
429→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
430→          return next;
431→        });
432→
433→        processedCountRef.current.set(agentId, chatMessages.length);
434→        setLoadedAgents((prev) => {
435→          if (prev.has(agentId)) return prev;
436→          const next = new Set(prev);
437→          next.add(agentId);
438→          return next;
439→        });
440→        return;
441→      }
442→
443→      // ── history_cleared: wipe local messages for this agent ──
444→      if (data.type === "history_cleared") {
445→        updateAgent(data.agentId, (prev) => ({
446→          ...prev,
447→          messages: [],
448→          rawMessages: [],
449→        }));
450→        processedCountRef.current.set(data.agentId, 0);
451→        return;
452→      }
453→
454→      // ── cli_disconnected: show system message ──
455→      if (data.type === "cli_disconnected") {
456→        updateAgent(data.agentId, (prev) => ({
457→          ...prev,
458→          messages: [
459→            ...prev.messages,
460→            {
461→              id: nextId(),
462→              role: "system",
463→              content: "CLI session ended",
464→              timestamp: Date.now(),
465→            },
466→          ],
467→        }));
468→        return;
469→      }
470→
471→      // ── cli_connected: show system message ──
472→      if (data.type === "cli_connected") {
473→        updateAgent(data.agentId, (prev) => {
474→          const isReconnect = prev.messages.length > 0;
475→          return {
476→            ...prev,
477→            messages: [
478→              ...prev.messages,
479→              {
480→                id: nextId(),
481→                role: "system",
482→                content: isReconnect ? "CLI reconnected" : "CLI connected",
483→                timestamp: Date.now(),
484→              },
485→            ],
486→          };
487→        });
488→        return;
489→      }
490→
491→      // ── agent_list: reconcile sidebar state from server ──
492→      if (data.type === "agent_list") {
493→        const serverAgents = data.agents as AgentInfo[];
494→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
495→        setAgents((prev) => {
496→          const next = new Map(prev);
497→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
498→
499→          // Update or add agents from server
500→          for (const info of serverAgents) {
501→            const existing = next.get(info.agentId);
502→            if (existing) {
503→              next.set(info.agentId, {
504→                ...existing,
505→                status: info.status,
506→                tmuxSession: info.tmuxSession,
507→                label: info.label,
508→              });
509→            } else {
510→              next.set(info.agentId, {
511→                status: info.status,
512→                messages: [],
513→                rawMessages: [],
514→                label: info.label,
515→                tmuxSession: info.tmuxSession,
516→                createdAt: info.createdAt,
517→              });
518→            }
519→          }
520→
521→          // Remove agents no longer on the server
522→          for (const id of next.keys()) {
523→            if (!serverIds.has(id)) {
524→              next.delete(id);
525→            }
526→          }
527→
528→          return next;
529→        });
530→        setAgentOrder(serverAgents.map((a) => a.agentId));
531→        setInitialLoadDone(true);
532→
533→        // No auto-select: leave user on the new-agent creation screen
534→        // until they explicitly pick an agent or spawn a new one.
535→        return;
536→      }
537→
538→      // ── spawned: auto-select the newly created agent ──
539→      if (data.type === "spawned") {
540→        setActiveAgentId(data.agentId);
541→        return;
542→      }
543→
544→      // ── status: update a specific agent's status ──
545→      if (data.type === "status") {
546→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
547→        return;
548→      }
549→
550→      // ── error: append to agent's message list ──
551→      if (data.type === "error") {
552→        updateAgent(data.agentId, (prev) => ({
553→          ...prev,
554→          messages: [
555→            ...prev.messages,
556→            {
557→              id: nextId(),
558→              role: "system",
559→              content: `Error: ${data.error}`,
560→              timestamp: Date.now(),
561→            },
562→          ],
563→        }));
564→        // Track processed count for dedup
565→        processedCountRef.current.set(
566→          data.agentId,
567→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
568→        );
569→        return;
570→      }
571→
572→      // ── relay: append or replace claude message in agent's history ──
573→      if (data.type === "relay") {
574→        const agentId = data.agentId;
575→        const rawMsg = data.message;
576→        const chatMsg = relayChatMessage(agentId, data);
577→        const dedupKey = getRelayDedupKey(data);
578→
579→        updateAgent(agentId, (prev) => {
580→          // Dedup raw messages: replace previous snapshot with same dedup key
581→          let nextRaw: ClaudeMessage[];
582→          if (dedupKey) {
583→            const existingIdx = findLastRawIndex(prev.rawMessages, data);
584→            if (existingIdx >= 0) {
585→              nextRaw = [...prev.rawMessages];
586→              nextRaw[existingIdx] = rawMsg;
587→            } else {
588→              nextRaw = [...prev.rawMessages, rawMsg];
589→            }
590→          } else {
591→            nextRaw = [...prev.rawMessages, rawMsg];
592→          }
593→
594→          if (!chatMsg) return { ...prev, rawMessages: nextRaw };
595→
596→          // Dedup chat messages: if this relay has a stable dedup key,
597→          // replace the existing ChatMessage with the same id instead of appending.
598→          let nextMessages: ChatMessage[];
599→          if (chatMsg.id.startsWith("dedup-")) {
600→            const existingIdx = prev.messages.findIndex((m) => m.id === chatMsg.id);
601→            if (existingIdx >= 0) {
602→              nextMessages = [...prev.messages];
603→              nextMessages[existingIdx] = chatMsg;
604→            } else {
605→              nextMessages = [...prev.messages, chatMsg];
606→            }
607→          } else {
608→            nextMessages = [...prev.messages, chatMsg];
609→          }
610→
611→          return { ...prev, rawMessages: nextRaw, messages: nextMessages };
612→        });
613→        if (chatMsg) {
614→          // Track processed count for dedup
615→          processedCountRef.current.set(
616→            agentId,
617→            (processedCountRef.current.get(agentId) ?? 0) + 1
618→          );
619→        }
620→        return;
621→      }
622→    };
623→  }, [updateAgent]);
624→
625→  useEffect(() => {
626→    closingRef.current = false;
627→    connect();
628→    return () => {
629→      closingRef.current = true;
630→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
631→      wsRef.current?.close();
632→    };
633→  }, [connect]);
634→
635→  const send = useCallback((data: object) => {
636→    if (wsRef.current?.readyState === WebSocket.OPEN) {
637→      wsRef.current.send(JSON.stringify(data));
638→    }
639→  }, []);
640→
641→  // Request history for the active agent if not already loaded.
642→  useEffect(() => {
643→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
644→    log("requesting history for", activeAgentId);
645→    send({ type: "request_history", agentId: activeAgentId });
646→  }, [activeAgentId, loadedAgents, send]);
647→
648→  const spawnAgent = useCallback(
649→    (prompt: string) => {
650→      send({ type: "spawn", prompt });
651→    },
652→    [send]
653→  );
654→
655→  const sendMessage = useCallback(
656→    (content: string) => {
657→      if (!activeAgentId) return;
658→      // Optimistically add user message to local state
659→      updateAgent(activeAgentId, (prev) => ({
660→        ...prev,
661→        messages: [
662→          ...prev.messages,
663→          {
664→            id: nextId(),
665→            role: "user",
666→            content,
667→            timestamp: Date.now(),
668→          },
669→        ],
670→      }));
671→      send({ type: "send_message", agentId: activeAgentId, content });
672→    },
673→    [send, activeAgentId, updateAgent]
674→  );
675→
676→  const respondToControl = useCallback(
677→    (requestId: string, allow: boolean) => {
678→      if (!activeAgentId) return;
679→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
680→      updateAgent(activeAgentId, (prev) => ({
681→        ...prev,
682→        messages: prev.messages.map((m) =>
683→          m.controlRequest?.id === requestId
684→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
685→            : m
686→        ),
687→      }));
688→    },
689→    [send, activeAgentId, updateAgent]
690→  );
691→
692→  /** Respond to an AskUserQuestion control request with the user's selections. */
693→  const respondToUserQuestion = useCallback(
694→    (requestId: string, answers: Record<string, string>) => {
695→      if (!activeAgentId) return;
696→      send({
697→        type: "control_response",
698→        agentId: activeAgentId,
699→        request_id: requestId,
700→        allow: true,
701→        answers,
702→      });
703→      updateAgent(activeAgentId, (prev) => ({
704→        ...prev,
705→        messages: prev.messages.map((m) =>
706→          m.userQuestion?.requestId === requestId
707→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
708→            : m
709→        ),
710→      }));
711→    },
712→    [send, activeAgentId, updateAgent]
713→  );
714→
715→  // ── Agent management actions ──────────────────────────────────────────────
716→
717→  const killAgent = useCallback(
718→    (agentId: string) => {
719→      send({ type: "kill_agent", agentId });
720→    },
721→    [send]
722→  );
723→
724→  const deleteAgent = useCallback(
725→    (agentId: string) => {
726→      send({ type: "delete_agent", agentId });
727→      // Deselect if we just deleted the active agent
728→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
729→    },
730→    [send]
731→  );
732→
733→  const renameAgent = useCallback(
734→    (agentId: string, label: string) => {
735→      send({ type: "rename_agent", agentId, label });
736→    },
737→    [send]
738→  );
739→
740→  const clearHistory = useCallback(
741→    (agentId: string) => {
742→      send({ type: "clear_history", agentId });
743→    },
744→    [send]
745→  );
746→
747→  // ── Task actions ──────────────────────────────────────────────────────────
748→
749→  const createTask = useCallback(
750→    (title: string, description: string, priority: TaskPriority) => {
751→      send({ type: "create_task", title, description, priority });
752→    },
753→    [send]
754→  );
755→
756→  const updateTask = useCallback(
757→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
758→      send({ type: "update_task", taskId, updates });
759→    },
760→    [send]
761→  );
762→
763→  const deleteTask = useCallback(
764→    (taskId: string) => {
765→      send({ type: "delete_task", taskId });
766→    },
767→    [send]
768→  );
769→
770→  const delegateTask = useCallback(
771→    (taskId: string) => {
772→      send({ type: "delegate_task", taskId });
773→    },
774→    [send]
775→  );
776→
777→  // Derived values for the active agent
778→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
779→  const activeStatus = useMemo<AgentStatus>(
780→    () => activeAgent?.status ?? "idle",
781→    [activeAgent?.status]
782→  );
783→  const activeMessages = useMemo<ChatMessage[]>(
784→    () => activeAgent?.messages ?? [],
785→    [activeAgent?.messages]
786→  );
787→  const activeRawMessages = useMemo<ClaudeMessage[]>(
788→    () => activeAgent?.rawMessages ?? [],
789→    [activeAgent?.rawMessages]
790→  );
791→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
792→
793→  return {
794→    connected,
795→    initialLoadDone,
796→    historyLoading,
797→    agents,
798→    agentOrder,
799→    activeAgentId,
800→    setActiveAgentId,
801→    activeStatus,
802→    activeMessages,
803→    activeRawMessages,
804→    spawnAgent,
805→    sendMessage,
806→    respondToControl,
807→    respondToUserQuestion,
808→    killAgent,
809→    deleteAgent,
810→    renameAgent,
811→    clearHistory,
812→    tasks,
813→    createTask,
814→    updateTask,
815→    deleteTask,
816→    delegateTask,
817→  };
818→}
819→

